 // assets/js/search.js

// --- normalizer (same as in slimify) ---
function normalize(str) {
  return String(str || '')
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .replace(/[^\p{Letter}\p{Number}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

// --- modality config (adjust codes if needed) ---
const MODALITY = {
  TRAIN: new Set([100]),
  HEV:   new Set([109]),
  BUS:   new Set([200]),
};
function hasAny(set, arr) { if (!Array.isArray(arr)) return false; for (const x of arr) if (set.has(x)) return true; return false; }
function isTrain(doc)   { return hasAny(MODALITY.TRAIN, doc.m); }
function isHev(doc)     { return hasAny(MODALITY.HEV, doc.m); }
function isBus(doc)     { return hasAny(MODALITY.BUS, doc.m); }

// --- category priority: 0 best ---
function categoryPriority(doc) {
  if (doc.i108 && isTrain(doc)) return 0; // 108_1 trains first
  if (isTrain(doc))             return 1; // regular trains
  if (isHev(doc))               return 2; // HÉV
  return 3;                                // bus/other/unknown
}

// --- globals ---
let mini = null;
let indexReady = false;

// --- init once (synchronous, since stations are inlined) ---
function initIndexOnce() {
  if (indexReady) return;
  if (!window.MiniSearch) {
    console.error('MiniSearch not found. Check script order.');
    return;
  }
  if (!Array.isArray(stations)) {
    console.error('stations data not found. Ensure stations-data.js is loaded before this file.');
    return;
  }
  console.log('Stations available:', stations.length);

  mini = new window.MiniSearch({
    idField: 'c',
    fields: ['n', 'a'], // canonical name + aliases
    storeFields: ['c','n','a','i108','hu','iso','m','nn'],
    processTerm: term => normalize(term),
    searchOptions: { prefix: true, fuzzy: 0.2, boost: { n: 2 } }
  });

  mini.addAll(stations);
  indexReady = true;

  // Diagnostics
  console.log('✅ MiniSearch index ready. Document count:', mini.documentCount);
  if (mini.documentCount === 0) {
    console.warn('Index has 0 docs. Check that stations objects have "n" (name) and "c" (code).');
  }
}

// --- scoring (MiniSearch score + business boosts) ---
function scoreDoc(doc, queryRaw) {
  const q = normalize(queryRaw);
  let score = doc.score || 0;

  // code-based boosts
  if (doc.c === queryRaw)             score += 60;
  else if (doc.c.startsWith(queryRaw)) score += 28;

  // name-based boosts
  const nn = doc.nn || normalize(doc.n);
  if (nn === q)            score += 35;
  else if (nn.startsWith(q)) score += 18;
  else if (nn.includes(q))   score += 6;

  // category boosts
  if (doc.i108 && isTrain(doc)) score += 15;
  if (isTrain(doc))             score += 10;
  else if (isHev(doc))          score += 4;

  // country bias
  if (doc.hu) score += 6;

  return score;
}

// --- transform doc -> your UI shape ---
function toDisplayEntry(doc) {
  return {
    id: doc.c,
    name: doc.n,
    products: {
      train:    isTrain(doc),
      suburban: isHev(doc),
      bus:      isBus(doc)
    }
  };
}

// --- main search function (called on input) ---
window.searchLocations = function searchLocations() {
  initIndexOnce();

  const el = document.getElementById('searchInput');
  const userInput = (el?.value || '').trim();

  // if empty, clear list
  if (!userInput) {
    displayResults([]);
    return;
  }

  if (!indexReady) {
    console.warn('Index not ready yet.');
    displayResults([]);
    return;
  }

  // MiniSearch query
  const hits = mini.search(userInput, { prefix: true, fuzzy: 0.2, boost: { n: 2 } });

  // DEBUG: show why it's empty
  if (hits.length === 0) {
    console.warn('No hits for:', userInput);
    // Quick self-test: try first 3 station names as a sanity check
    const sample = window.stations.slice(0, 3).map(s => s.n);
    console.log('Sample names:', sample);
  }

  // rank: category first, then composite score, then name
  const ranked = hits.map(h => {
    const prio = categoryPriority(h);
    const composite = scoreDoc(h, userInput);
    return { doc: h, prio, composite };
  });

  ranked.sort((a, b) => {
    if (a.prio !== b.prio) return a.prio - b.prio;
    if (a.composite !== b.composite) return b.composite - a.composite;
    return a.doc.n.localeCompare(b.doc.n, 'hu');
  });

  const top = ranked.slice(0, 20).map(x => toDisplayEntry(x.doc));
  // log what you're sending to UI
  console.log('Top results:', top);

  displayResults(top);
};

// --- optionally kick off an initial init so first keystroke is fast ---
document.addEventListener('DOMContentLoaded', initIndexOnce);


function displayResults(data) {
    const resultsContainer = document.getElementById('results');
    resultsContainer.innerHTML = ''; // Clear previous results

    data.forEach(entry => {
        // Check if suburban is true
        const isSuburban = entry.products?.suburban;
        const isTrain    = entry.products?.train;
        const isBus      = entry.products?.bus;

        console.log(isSuburban);


        if (
            entry.products?.train ||
            entry.products?.suburban || 
            entry.products?.bus 
        ) {

            // Create a div with class "suggestion"
            const suggestionDiv = document.createElement('div');
            suggestionDiv.classList.add('suggestion');

            // Create a span for the name
            const nameSpan = document.createElement('span');
            nameSpan.textContent = entry.name;

            // Create an anchor element with a link based on the selected search type (departure or arrival)
            const link = document.createElement('a');
            link.href = `departure.html?station=${entry.id}`;

            // If suburban is true, append an image to the link with class "bigicon"
            if (isSuburban) {
                const img = document.createElement('img');
                img.src = '../assets/icons/suburban.svg';
                img.alt = 'Suburban Icon';
                img.classList.add('bigicon');
                img.classList.add('inverted');
                link.appendChild(img);
            }

            if (isBus) {
                const img = document.createElement('img');
                img.src = '../assets/icons/busstop.svg';
                img.alt = 'Bus Icon';
                img.classList.add('bigicon');
                img.classList.add('inverted');
                link.appendChild(img);
            }

            if (isTrain) {
                const img = document.createElement('img');
                img.src = '../assets/icons/rail.svg';
                img.alt = 'Rail Icon';
                img.classList.add('bigicon');
                img.classList.add('inverted');
                link.appendChild(img);
            }

            // Append the nameSpan and link to the suggestionDiv
            suggestionDiv.appendChild(nameSpan);
            suggestionDiv.appendChild(link);

            // Add a click event listener to the suggestionDiv
            suggestionDiv.addEventListener('click', () => {
                window.location.href = link.href; // Redirect to the link when the div is clicked
            });

            // Append the suggestionDiv to the results container
            resultsContainer.appendChild(suggestionDiv);
        }
    });
}

/**
 * Returns the canonical station name and modalities for a given station ID (code).
 * @param {string} stationId - The station's code (value of `c` in your stations data)
 * @returns {{name: string, modalities: number[]}|null}
 */
window.getStationInfoById = function getStationInfoById(stationId) {
  if (!stationId || !Array.isArray(window.stations)) {
    console.warn('getStationInfoById: stations not initialized or invalid id');
    return null;
  }

  // Direct lookup from the in-memory array
  const match = window.stations.find(s => s.c === stationId);

  if (match) {
    return {
      name: match.n || null,
      modalities: Array.isArray(match.m) ? match.m : []
    };
  }

  // Optional fallback: if MiniSearch has the index loaded
  if (window.mini && typeof window.mini.document === 'function') {
    const doc = window.mini.document(stationId);
    if (doc) {
      return {
        name: doc.n || null,
        modalities: Array.isArray(doc.m) ? doc.m : []
      };
    }
  }

  console.warn('Station not found for id:', stationId);
  return null;
};


window.addEventListener("load", () => {
    if ("serviceWorker" in navigator) {
        navigator.serviceWorker.register("../service-worker.js");
    }
});

fetchAndDisplayData();